test "coding_agent product all surface shards" {
    const gpa = std.testing.allocator;
    const skills = try listSkills(gpa);
    defer gpa.free(skills);
    try std.testing.expect(std.mem.indexOf(u8, skills, "skill_0_0") != null);
    try std.testing.expect(std.mem.indexOf(u8, skills, "skill_19_49") != null);
    const bodies = try expandAllTemplates(gpa, "/tmp", "m");
    defer gpa.free(bodies);
    try std.testing.expect(bodies.len > 0);
    try std.testing.expect(skillBody("skill_3_7") != null);
}
